output_text:
[
  {
    "id": "must_take_entry_cart",
    "text": "A shopper must collect the entry cart before doing the trip, even when only a small number of items is needed.",
    "abstraction": {
      "state_properties": {
        "entry_cart_bay": "at(1,5)",
        "carrying_cart": "hasCart"
      },
      "events": {
        "entry_cart_taken": {
          "pre": {
            "and": [
              "entry_cart_bay",
              "PICKUP_CART"
            ]
          },
          "post": "carrying_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "entry_cart_taken"
    }
  },
  {
    "id": "items_only_into_cart",
    "text": "Items may only be picked up while the shopper has a cart, not while shopping empty-handed.",
    "abstraction": {
      "state_properties": {
        "carrying_cart": "hasCart",
        "no_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        },
        "cart_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "carrying_cart"
            ]
          },
          "post": null
        },
        "hand_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "no_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "hand_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Shoppers are forbidden from carrying goods by hand in the store.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "cart_available_to_carry_goods": "hasCart"
      },
      "events": {
        "became_hand_full": {
          "pre": {
            "not": "handFull"
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "return_taken_cart_to_front",
    "text": "Any cart taken from the entry bay must be returned to the front return bay before the shopper leaves.",
    "abstraction": {
      "state_properties": {
        "entry_cart_bay": "at(1,5)",
        "front_return_bay": "at(0,1)",
        "carrying_cart": "hasCart",
        "cart_parked_at_front_return_bay": "cartAt(0,1)"
      },
      "events": {
        "entry_cart_taken": {
          "pre": {
            "and": [
              "entry_cart_bay",
              "PICKUP_CART"
            ]
          },
          "post": "carrying_cart"
        },
        "front_cart_returned": {
          "pre": {
            "and": [
              "front_return_bay",
              "carrying_cart",
              "LEAVE_CART"
            ]
          },
          "post": {
            "and": [
              "cart_parked_at_front_return_bay",
              {
                "not": "hasCart"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "entry_cart_taken",
      "discharge": "front_cart_returned"
    }
  },
  {
    "id": "leave_cart_only_at_front",
    "text": "A shopper may put down a cart only in the designated front return bay.",
    "abstraction": {
      "state_properties": {
        "front_return_bay": "at(0,1)",
        "outside_front_return_bay": {
          "not": "front_return_bay"
        },
        "carrying_cart": "hasCart"
      },
      "events": {
        "cart_left": {
          "pre": "LEAVE_CART",
          "post": {
            "not": "hasCart"
          }
        },
        "cart_left_outside_front_return_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_front_return_bay"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_left_outside_front_return_bay"
    }
  },
  {
    "id": "no_exit_with_unreturned_cart",
    "text": "A shopper is forbidden to exit while still holding a cart or while the cart is not parked at the front return bay.",
    "abstraction": {
      "state_properties": {
        "carrying_cart": "hasCart",
        "cart_parked_at_front_return_bay": "cartAt(0,1)",
        "cart_not_returned_to_front": {
          "not": "cart_parked_at_front_return_bay"
        },
        "cart_exit_violation_state": {
          "or": [
            "carrying_cart",
            "cart_not_returned_to_front"
          ]
        }
      },
      "events": {
        "exit_attempt": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "cart_exit_violation_state"
        ]
      }
    }
  },
  {
    "id": "shopping_with_cart_creates_return_duty",
    "text": "Once an item has been placed into the cart, the cart must eventually be returned to the front return bay before exit.",
    "abstraction": {
      "state_properties": {
        "front_return_bay": "at(0,1)",
        "carrying_cart": "hasCart",
        "cart_parked_at_front_return_bay": "cartAt(0,1)"
      },
      "events": {
        "item_taken_into_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "carrying_cart"
            ]
          },
          "post": "carrying_cart"
        },
        "front_cart_returned": {
          "pre": {
            "and": [
              "front_return_bay",
              "carrying_cart",
              "LEAVE_CART"
            ]
          },
          "post": {
            "and": [
              "cart_parked_at_front_return_bay",
              {
                "not": "hasCart"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_taken_into_cart",
      "discharge": "front_cart_returned"
    }
  },
  {
    "id": "after_cart_return_exit_on_foot",
    "text": "After returning the cart to the front bay, the shopper must proceed to exit without the cart.",
    "abstraction": {
      "state_properties": {
        "front_return_bay": "at(0,1)",
        "cart_parked_at_front_return_bay": "cartAt(0,1)",
        "on_foot": {
          "not": "hasCart"
        },
        "at_exit_cell": "at(9,5)"
      },
      "events": {
        "front_cart_returned": {
          "pre": {
            "and": [
              "front_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": {
            "and": [
              "cart_parked_at_front_return_bay",
              "on_foot"
            ]
          }
        },
        "exit_on_foot": {
          "pre": {
            "and": [
              "EXIT",
              "at_exit_cell",
              "on_foot"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "front_cart_returned",
      "discharge": "exit_on_foot"
    }
  }
]
